WITH valid_shipments AS (SELECT * FROM shipments WHERE order_id IN (11, 19, 34) OR MONTH(shipped_date) IN (4, 5, 12)), shipments_stats AS (SELECT CASE WHEN YEAR(delivered_date) < 2024 THEN 'before_2024' WHEN YEAR(delivered_date) = 2024 THEN '2024' ELSE 'after_2024' END AS delivered_cohort, ROUND(AVG(cost), 2) AS avg_cost FROM valid_shipments GROUP BY CASE WHEN YEAR(delivered_date) < 2024 THEN 'before_2024' WHEN YEAR(delivered_date) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT * FROM shipments_stats WHERE avg_cost < 49;
